import { test, expect } from './fixtures';
import type { APIRequestContext } from '@playwright/test';

// The Content-Security-Policy no longer allows third-party hosts the web UI
// doesn't use.  The header is generated by scripts/ManageApacheContentPolicy.sh
// from its DEFAULT_VALUES (run-web.sh regenerates it for the tree it serves):
//
// - fpp 28d1f6a78 ("Stop the web UI fetching fonts and from third-party
//   hosts"): font-src allowed https://fonts.scalar.com, so the Scalar API docs
//   viewer (/api/) fetched its webfonts from there, sending every visitor's IP
//   to a host the operator never chose.  font-src is now local only, and
//   api.html turns Scalar's default fonts off.
// - fpp 55f977d8a ("ipapi.co is no longer needed in CSP"): connect-src allowed
//   https://ipapi.co, though the lookup goes through the player's api/geoip.
// - fpp ceffffbec ("revert change as unneeded following testing"): took
//   https://ipapi.co back out of default-src, the same day 2e593d623 put it in.
// - fpp a0ba5016a ("www.w3.org is not needed in CSP"): default-src and img-src
//   allowed http://www.w3.org.

// The API docs page itself, Scalar rendering /api/openapi.json, is fpp
// 9bab76c81's ("feat: add scalar for API documentation").

async function cspOf(request: APIRequestContext, path: string) {
  const res = await request.get(path);
  expect(res.status()).toBe(200);
  const header = res.headers()['content-security-policy'];
  // The control: the page is served with a CSP that has the directives checked.
  expect(header, `no Content-Security-Policy on ${path}`).toBeTruthy();
  const directives: Record<string, string[]> = {};
  for (const part of header.split(';')) {
    const [name, ...values] = part.trim().split(/\s+/);
    if (name) directives[name] = values;
  }
  for (const d of ['default-src', 'connect-src', 'font-src', 'img-src']) {
    expect(directives, `CSP has no ${d}: ${header}`).toHaveProperty(d);
  }
  expect(directives['default-src']).toContain("'self'");
  expect(directives['connect-src']).toContain('https://api.github.com');
  return { header, directives };
}

test.afterEach(async ({ page }) => {
  await page.unrouteAll({ behavior: 'ignoreErrors' });
});

test('CSP: font-src allows no third-party font host, and the API docs fetch none', async ({ request, page, baseURL }) => {
  const { header, directives } = await cspOf(request, '/api/api.html');
  expect(directives['font-src']).toEqual(["'self'", 'data:']);
  for (const host of ['fonts.scalar.com', 'fonts.googleapis.com', 'fonts.gstatic.com']) {
    expect(header).not.toContain(host);
  }

  // The Scalar viewer itself requests no font from anywhere but the player.
  // (Every other host is aborted, so nothing leaves the test either way.)
  const origin = new URL(baseURL!).origin;
  const foreignFonts: string[] = [];
  page.on('request', (req) => {
    if (req.resourceType() === 'font' && new URL(req.url()).origin !== origin) foreignFonts.push(req.url());
  });
  await page.route((url) => url.origin !== origin, (route) => route.abort());
  const spec = page.waitForResponse((r) => r.url().endsWith('/api/openapi.json') && r.ok());
  await page.goto('/api/api.html');
  // The control: Scalar loaded the spec and rendered it (its content is
  // client-built).
  await spec;
  await expect(page.getByRole('heading', { name: 'FPP API' }).first()).toBeVisible({ timeout: 30_000 });
  await page.waitForLoadState('networkidle');
  expect(foreignFonts).toEqual([]);
});

test('CSP: connect-src does not allow ipapi.co', async ({ request }) => {
  const { header, directives } = await cspOf(request, '/index.php');
  expect(directives['connect-src']).toContain("'self'");
  expect(header).not.toContain('ipapi.co');
});

test('CSP: default-src and img-src do not allow www.w3.org', async ({ request }) => {
  const { header, directives } = await cspOf(request, '/index.php');
  expect(directives['img-src']).toEqual(expect.arrayContaining(["'self'", 'blob:', 'data:']));
  expect(header).not.toContain('w3.org');
});
